language.text:
LANGUAGE adopted-7f72c09aa86e (19 adopted rules)
rule-672: CONTRACT {"trigger":"Every message.","encoder":["Send one unit without chunk headers or separators such as [part X/Y] or ---END---.","Prefix actionable lines with ^. In instruction-heavy messages, use narrative only for context that cannot be an instruction."],"decoder":["Preserve ^ and reconstruct line content only as authorized. Act on ^ lines; all other lines are narrative."],"invalid_if":["Chunk markers are added, ^ is lost, or narrative is treated as an instruction."],"overrides":[]}
rule-673: CONTRACT {"trigger":"Text outside exact-preservation requirements.","encoder":["May omit punctuation .,:;!?- and capitalization except in numbers, units, and identifiers.","In narrative, omit a/an/the; of/in/for/on/at/to; is/are/was/were/be/been when meaning stays clear.","Also omit has/have/had before past participles and that/which/who/whom introducing subordinate clauses when clear.","Keep binding and, with, because, or, but, so."],"decoder":["Infer omitted words, punctuation, and case using source context. Restore the most plausible grammar and original logical flow.","Infer only allowed word categories; introduce no relationships or contradictions of preserved content."],"invalid_if":["Omission obscures meaning or reconstruction changes facts or logic."],"overrides":[]}
rule-674: CONTRACT {"trigger":"Numeric literals, ranges, and money in any line.","encoder":["Keep value-bearing punctuation, especially decimal points in all numbers, unit-bearing values, and percentages.","A leading decimal zero may be omitted only for values below 1, subject to atomic exactness.","Keep range delimiters exactly: hyphen, en-dash, or colon. Keep money verbatim, including currency symbols, decimals, and thousands commas."],"decoder":["Interpret .8 as 0.8 where omission is allowed; ranges are continuous between endpoints; money is one numeric entity with its value and currency."],"invalid_if":["Value, currency, or range changes."],"overrides":[]}
rule-675: CONTRACT {"trigger":"Technical identifiers and strings whose exact characters serve as unique references.","encoder":["Preserve technical punctuation and case, including flags, endpoints, zones, paths, emails, and hyphenated segments.","Keep technical colon-plus-qualifier unbroken.","Enclose every opaque reference in backticks; preserve all characters and whitespace. Verify against the source before sending.","No compression may change characters inside an opaque reference."],"decoder":["For non-opaque technical syntax, keep colon qualifiers attached rather than interpreting slot separators.","Strip opaque backticks, output verbatim, and validate character-for-character.","Thereafter the identifier remains solely an opaque unique reference; never parse its interior."],"invalid_if":["An identifier changes, opaque enclosure is missing, or internal characters acquire language syntax."],"overrides":["atoms"]}
rule-676: CONTRACT {"trigger":"Source facts in all lines; narrative order and rationale where specified.","encoder":["Keep named entities, people, organizations, locations, system/region/environment identifiers, dates, times, deadlines, penalty clauses, quantities, numeric qualifiers, and explicit stakes; preserve case, punctuation, and leading zeros.","Put event names, venues, constraints, deadlines, counts, capacity limits, stakes, ordinals, sequence indicators, comparative qualifiers, and their logical connectors before the directives they justify.","Keep if, then, unless, because, and so exactly in conditional or sequential chains.","Keep colloquial technical-unit abbreviations as written."],"decoder":["Retain facts, scope, exact order, rationale, and logical relationships.","Interpret unit abbreviations with the source's intended unit; expand only if the source explicitly expands them."],"invalid_if":["Required context is absent, misplaced, normalized, or logically changed."],"overrides":[]}
rule-677: CONTRACT {"trigger":"A string repeats at least 3 times within one message.","encoder":["May define @short=long_form on its own line, then use @short.","Require definition tokens + uses × alias tokens < uses × original tokens.","Store complete bundles with delimiters; join common-noun words with underscores in narrative aliases. Action aliases may appear in any directive.","For opaque aliases, store a literal backticked source copy. Verify character-for-character before storing; never compress its interior."],"decoder":["Substitute the exact original string, including restored common-noun spacing."],"invalid_if":["Repetition or savings threshold fails, a definition is altered, or substitution differs."],"overrides":[]}
rule-678: CONTRACT {"trigger":"Directive content outside protected atoms.","encoder":["May use slots; recommended order: action, object, condition, deadline, rationale. Omit articles and prepositions when slots convey their relation.","May share action and qualifier once before a colon and comma-separated items. Write distinct qualifiers as separate directives.","May replace by/at/to/for before a time, deadline, or recipient with a colon attached to the preceding slot.","May replace argument and/or with +/|. Preserve an action's required preposition or use a colon.","May replace greater than/older than with > and less than/newer than with <."],"decoder":["Infer slot relations; apply shared action and qualifier to each listed item. Expand colons to the appropriate preposition and +/| to and/or.","Read >/< as older/newer than before durations and greater/less than before plain numeric values."],"invalid_if":["Slots or lists change attachment, scope, comparison, or qualifiers."],"overrides":[]}
rule-679: CONTRACT {"trigger":"Every measured quantity or allocation in any source line.","encoder":["Scan and bundle before omissions or any other compression.","Start at a numeric literal or comparison phrase/symbol, including greater than, at least, older than, newer than, >, <.","Include an allocation action verb when immediately followed by a numeric literal or comparison phrase.","Continue through the last unit, target, or attached qualifier; stop before a conjunction starting an independent clause outside the measured relationship.","Use one atom containing every value, unit, comparison, relational preposition, and target. Verify completeness and exact source characters before sending."],"decoder":["Apply atoms; retain the role of an exact measured fact.","Never normalize decimals or leading zeros, convert formats, expand units, reorder components, or reinterpret qualifiers."],"invalid_if":["Any measured component is outside or split across atoms, altered, or missing."],"overrides":[]}
rule-680: CONTRACT {"trigger":"Every time, date, relative deadline, duration, range, ordering relationship, or sequence marker directly attached to a temporal element.","encoder":["Scan every source line and bundle before omissions or any other compression.","Start at the first introducing word, link, temporal element, or attached sequence marker; include through the last temporal element and all attached qualifiers.","Keep time zones, locale, locative qualifiers, and every link forming a combined ordering or range in one atom.","Stop before a conjunction starting an independent clause outside the temporal relationship.","Thus <after 3 PM and before 5 PM> stays whole; wait <until 3 PM> and then proceed stops before the new action."],"decoder":["Apply atoms. Preserve the exact temporal role; internal words, conjunctions, and symbols remain opaque after reconstruction."],"invalid_if":["A temporal component or link is omitted, split, normalized, or absorbed from an unrelated clause."],"overrides":[]}
rule-681: CONTRACT {"trigger":"A descriptive noun or noun phrase directly precedes and attaches to an identifier, name, or description, unless already covered by a more specific atom.","encoder":["Bundle from the label's first word through the attached entity's last word. Stop before a conjunction starting an independent clause outside the attachment."],"decoder":["Apply atoms; retain exact label wording and attachment without inference, detachment, or splitting."],"invalid_if":["Label wording, scope, or attachment differs from the source."],"overrides":[]}
rule-682: CONTRACT {"trigger":"Two distinct semantic categories are syntactically linked, including actions, conditions, causes, effects, qualifications, instructions, entities, measured facts, and temporal constraints.","encoder":["Scan every line for because/so/if/unless/since/while, and/or, and for/with/by/to/at/from/before/after/until linking categories.","Bundle the complete relationship from the first category's first word through the linked category's last word, unless already fully captured in one atom.","Stop before a conjunction starting an independent clause outside that relationship.","Keep every linking word's spelling, case, and position; never symbolize, abbreviate, or omit it."],"decoder":["Apply atoms; validate every link and preserve the complete relationship."],"invalid_if":["A category or relational link is omitted, altered, detached, or split."],"overrides":[]}
rule-683: CONTRACT {"trigger":"Any contiguous source substring designated for exact atomic preservation, including all mandatory phrase bundles.","encoder":["Enclose the exact substring in <...>. Retain category-specific scope and completeness requirements.","Before sending, compare enclosed content with the contiguous source substring character-for-character; correct any mismatch."],"decoder":["Remove enclosing delimiters, output the content verbatim, and validate it character-for-character against the source; never normalize, abbreviate, reorder, omit, split, or alter it.","Treat reconstructed angle-bracket or backtick content as an indivisible semantic unit. Internal characters cannot become operators, slots, lists, directives, or bundle boundaries."],"invalid_if":["Required content is missing or split, comparison fails, or internal content is reinterpreted."],"overrides":["minimal","numbers","directives"]}
rule-684: CONTRACT {"trigger":"A linked descriptive attachment modifies a preceding noun and is not already captured as a measured fact, temporal phrase, label pair, or critical fact.","encoder":["Use the introducing conjunctions and prepositions listed in links.","Bundle from the introducer through the clause, stopping at clause-ending comma, period, colon, semicolon, or a new independent clause.","Use angle brackets under atoms, including the full descriptive attachment."],"decoder":["Apply atoms to reconstruct the attachment exactly."],"invalid_if":["The introducer, clause boundary, or attachment changes."],"overrides":[]}
rule-685: CONTRACT {"trigger":"An identical substring already angle-bracketed in the source under adopted bundling rules occurs at least 3 times.","encoder":["May define $ref=exact_bundled_phrase on its own line, then use $ref anywhere.","Store the entire bracketed substring verbatim and verify each occurrence character-for-character.","Require definition tokens + uses × reference tokens < uses × original bundle tokens.","Choose the eligible mechanism with greatest savings; use aliases for repeated unbracketed strings."],"decoder":["Substitute the stored bundle including its brackets; validate against the original source bundle."],"invalid_if":["Source eligibility, identity, repetition, or savings checks fail."],"overrides":[]}
rule-686: CONTRACT {"trigger":"A structural pattern with variable gaps repeats at least 3 times; use for within-line patterns with separate variable definitions.","encoder":["May write %template=pattern on its own line with placeholders $N, a dollar sign followed only by decimal digits.","Define each variable separately as $N=content. Bindings belong to the preceding template and are consumed on invocation.","Protect literal variable content with its required atomic delimiters.","Invoke as %template content1 content2 ... in placeholder order with exactly as many arguments as placeholders.","Arguments may be literal strings, aliases, or references. Templates and definitions may be reused for invocations with different contents.","Count the template definition, every variable definition, invocation token, and all variable content tokens including delimiters.","Verify every expanded instance against the source character-for-character after all substitutions."],"decoder":["Substitute aliases, then references, then expand templates before minimal-form reconstruction or other processing.","Substitute literal contents verbatim in placeholder positions, preserving structure and variable content."],"invalid_if":["Placeholder syntax, scope, argument count/order, protection, or reconstructed source match fails."],"overrides":[]}
rule-687: CONTRACT {"trigger":"At least 3 lines have an identical literal prefix and suffix with one variable middle.","encoder":["May define #pattern=prefix$suffix on its own line, with exactly one $ gap.","Include intended prefix/suffix spaces literally; add none around $ unless part of those literals.","Invoke each line as #pattern variable, where variable is the complete exact middle atom including delimiters.","Verify each reconstructed source line character-for-character."],"decoder":["Strip the variable's outer angle brackets or backticks; concatenate exact prefix + literal middle + exact suffix."],"invalid_if":["Multiple gaps, extra variable material, altered literal spacing, or a source mismatch occurs."],"overrides":[]}
rule-688: CONTRACT {"trigger":"At least 3 lines share only an identical prefix followed by variable items.","encoder":["May define %list=prefix$ on its own line; $ is final and there is no suffix.","Write each expansion on its own line as $ item, with item a complete atom including required delimiters.","Verify each reconstructed source line character-for-character."],"decoder":["Concatenate the exact prefix and item's literal content after removing its atomic delimiters; preserve source spacing."],"invalid_if":["A suffix, incomplete atom, changed spacing, or source mismatch occurs."],"overrides":[]}
rule-689: CONTRACT {"trigger":"A line differs from a previous line only in one complete atom, and an identical prefix occurs in at least 2 lines.","encoder":["May replace the prefix with a single $ token followed by the differing atom.","Reference the most recent line using that same prefix before a different atom. Verify the source prefix character-for-character."],"decoder":["Concatenate the referenced prefix and atom's literal content after removing its delimiters; require exact source-line reconstruction."],"invalid_if":["The prefix differs, the atom does not differ, or reconstruction loses any line content."],"overrides":[]}
rule-690: CONTRACT {"trigger":"At least 3 distinct lines share a global structural pattern with variable atomic substrings; prefix-only and fixed prefix/suffix forms use lists and patterns.","encoder":["May define #macro_name=pattern on its own line. Names contain only letters, digits, or underscores, with no spaces.","Keep all invariant text and punctuation exact; place $1, $2, ..., $N at variable positions. Each placeholder is $ followed only by decimal digits.","Invoke with #macro_name, a space, then exact delimited variable atoms in order separated by spaces.","Verify every expanded line against its source character-for-character."],"decoder":["Recognize definitions by #name=pattern.","Recognize invocations by exact first-token match to a previously defined name followed by a space; exclude #pattern.","Substitute aliases, then references, then expand macros before minimal-form reconstruction or other processing.","Replace each invocation line with the pattern, substituting whole variable tokens verbatim including delimiters."],"invalid_if":["Name recognition, placeholder syntax, variable order/protection, invariant text, or source match fails."],"overrides":[]}
